<?php
require __DIR__.'/../bootstrap.php'; require_super_admin();
function redirect_admin_destination(string $url): string { $url=trim($url); if(strlen($url)>2048 || !filter_var($url,FILTER_VALIDATE_URL)) throw new RuntimeException('Enter a valid destination URL.'); $scheme=strtolower((string)parse_url($url,PHP_URL_SCHEME)); if(!in_array($scheme,['http','https'],true) || !parse_url($url,PHP_URL_HOST)) throw new RuntimeException('Only HTTP and HTTPS destinations are allowed.'); return $url; }
$msg=''; if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); try { $action=(string)post('action','');
 if($action==='create') { $uid=(int)post('user_id',0); $slug=preg_replace('/[^A-Za-z0-9_-]/','',(string)post('slug','')); $dest=redirect_admin_destination((string)post('destination_url','')); if($uid<=0) throw new RuntimeException('Select an existing owner account.'); if(strlen($slug)<3||strlen($slug)>64) throw new RuntimeException('Alias must be 3–64 letters, numbers, underscores or hyphens.'); if(preg_match('/^(admin|api|login|signup|logout|links|qr|settings|dashboard|install)$/i',$slug)) throw new RuntimeException('That alias is reserved.'); $q=db()->prepare('SELECT id FROM users WHERE id=?');$q->execute([$uid]);if(!$q->fetchColumn())throw new RuntimeException('Owner account not found.'); db()->prepare("INSERT INTO short_links(user_id,slug,destination_url,title,status,created_at,updated_at) VALUES(?,?,?,?,'active',NOW(),NOW())")->execute([$uid,$slug,$dest,trim((string)post('title',''))]); policy_audit((int)current_user()['id'],'redirect.admin.create',[],['slug'=>$slug,'user_id'=>$uid]); flash('success','Redirect created and tracking enabled.'); redirect('/admin/redirects/');
 } elseif($action==='update') { $id=(int)post('id');$dest=redirect_admin_destination((string)post('destination_url',''));$title=trim((string)post('title',''));$status=(string)post('status','active');if(!in_array($status,['active','disabled'],true))throw new RuntimeException('Invalid redirect status.');$q=db()->prepare('SELECT id,slug,destination_url,status FROM short_links WHERE id=?');$q->execute([$id]);$before=$q->fetch();if(!$before)throw new RuntimeException('Redirect not found.');db()->prepare('UPDATE short_links SET destination_url=?,title=?,status=?,updated_at=NOW() WHERE id=?')->execute([$dest,$title,$status,$id]);policy_audit((int)current_user()['id'],'redirect.admin.update',$before,['destination_url'=>$dest,'title'=>$title,'status'=>$status]);flash('success','Redirect updated.');redirect('/admin/redirects/');
 } elseif($action==='delete') { $id=(int)post('id');$q=db()->prepare('SELECT id,slug,destination_url,status FROM short_links WHERE id=?');$q->execute([$id]);$before=$q->fetch();if(!$before)throw new RuntimeException('Redirect not found.');db()->prepare('DELETE FROM short_links WHERE id=?')->execute([$id]);policy_audit((int)current_user()['id'],'redirect.admin.delete',$before,[]);flash('success','Redirect and its click records deleted.');redirect('/admin/redirects/'); }
 } catch(Throwable $e) {$msg=$e->getMessage();} }
$range=(string)($_GET['range']??'30d');if(!in_array($range,['24h','7d','30d','90d'],true))$range='30d';$since=['24h'=>'24 HOUR','7d'=>'7 DAY','30d'=>'30 DAY','90d'=>'90 DAY'][$range];
$links=db()->query("SELECT l.id,l.user_id,l.slug,l.destination_url,l.title,l.status,l.clicks,l.created_at,l.updated_at,u.email,(SELECT COUNT(*) FROM link_clicks c WHERE c.link_id=l.id AND c.clicked_at>=DATE_SUB(NOW(),INTERVAL $since)) AS recent_clicks FROM short_links l JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 500")->fetchAll();$users=db()->query("SELECT id,email FROM users WHERE status='active' ORDER BY email LIMIT 500")->fetchAll();$title='Redirect Management';require __DIR__.'/../includes/header.php';
?><div class="page-head"><div><span class="eyebrow">ADMIN · URL ENGINE</span><h1>Redirects</h1><p>Manage URL aliases, destinations, status and click tracking centrally.</p></div><div class="analytics-range"><?php foreach(['24h','7d','30d','90d'] as $r):?><a class="pill <?=$range===$r?'active':''?>" href="?range=<?=$r?>"><?=$r?></a><?php endforeach;?></div></div><?php if($msg):?><div class="alert alert-error"><?=e($msg)?></div><?php endif;?>
<section class="card"><h2>Create redirect</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><label>Owner account<select name="user_id" required><option value="">Choose owner</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=e($u['email'])?> (#<?=$u['id']?>)</option><?php endforeach;?></select></label><label>Alias<input name="slug" minlength="3" maxlength="64" pattern="[A-Za-z0-9_-]+" required></label><label>Title<input name="title" maxlength="220"></label><label>Destination URL<input name="destination_url" type="url" maxlength="2048" required placeholder="https://example.com"></label><button class="btn" type="submit">Create redirect</button></form></section>
<section class="card"><h2>Existing redirects</h2><div class="table-wrap"><table><thead><tr><th>Alias / owner</th><th>Destination</th><th>All clicks</th><th><?=e($range)?> clicks</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($links as $l):?><tr><td><strong><?=e($l['slug'])?></strong><br><small><?=e($l['email'])?> · #<?=e((string)$l['id'])?></small><br><a href="/r/<?=rawurlencode($l['slug'])?>" target="_blank" rel="noopener">Open short link</a></td><td><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$l['id']?>"><input name="title" maxlength="220" value="<?=e($l['title']??'')?>" aria-label="Title"><input name="destination_url" type="url" maxlength="2048" required value="<?=e($l['destination_url'])?>" aria-label="Destination URL"><select name="status"><option value="active" <?=$l['status']==='active'?'selected':''?>>Active</option><option value="disabled" <?=$l['status']==='disabled'?'selected':''?>>Disabled</option></select><button class="btn small" type="submit">Save</button></form></td><td><?=number_format((int)$l['clicks'])?></td><td><?=number_format((int)$l['recent_clicks'])?></td><td><?=e($l['status'])?></td><td><form method="post" onsubmit="return confirm('Permanently delete this redirect and its click history?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$l['id']?>"><button class="btn danger small" type="submit">Delete</button></form></td></tr><?php endforeach;if(!$links):?><tr><td colspan="6" class="muted">No redirects found.</td></tr><?php endif;?></tbody></table></div><p class="muted">Showing at most 500 redirects. Click records are stored in the existing link_clicks table; deletion removes associated tracking data through the foreign-key cascade.</p></section><?php require __DIR__.'/../includes/footer.php'; ?>
